/**
 * 黄金矿工 - 钩子状态机
 * Gold Miner Hook State Machine
 */

// 钩子状态枚举
enum HookState {
  IDLE = 'IDLE',           // 空闲状态 - 等待玩家操作
  EXTENDING = 'EXTENDING', // 伸展状态 - 钩子向外移动
  RETRACTING = 'RETRACTING', // 收回状态 - 钩子带着物品返回
  CATCHING = 'CATCHING',   // 抓取状态 - 正在抓取物品
  RETURNING = 'RETURNING', // 回归状态 - 带着物品返回
  CAUGHT = 'CAUGHT',       // 已抓取 - 物品已被抓住
  MISSED = 'MISSED',       // 未抓中 - 钩子空返
  STUNNED = 'STUNNED'      // 眩晕状态 - 被攻击后无法操作
}

// 钩子方向
enum HookDirection {
  LEFT = -1,
  RIGHT = 1,
  UP = 0,
  DIAGONAL_UP_LEFT = -0.7,
  DIAGONAL_UP_RIGHT = 0.7,
  DIAGONAL_DOWN_LEFT = -1.4,
  DIAGONAL_DOWN_RIGHT = 1.4
}

// 物品类型
interface CollectibleItem {
  id: string;
  type: 'gold' | 'diamond' | 'stone' | 'chest' | 'enemy' | 'powerup';
  value: number;
  weight: number;
  x: number;
  y: number;
  radius: number;
  isCaught: boolean;
}

// 钩子配置
interface HookConfig {
  maxLength: number;           // 最大长度
  baseSpeed: number;           // 基础速度
  basePower: number;           // 基础拉力
  acceleration: number;        // 加速度
  friction: number;            // 摩擦力
  catchRadius: number;         // 抓取半径
  retractSpeedMultiplier: number; // 收回速度乘数（受重量影响）
}

// 钩子状态机上下文
interface HookContext {
  state: HookState;
  x: number;
  y: number;
  angle: number;               // 角度（弧度）
  length: number;              // 当前长度
  velocity: number;            // 当前速度
  caughtItem: CollectibleItem | null;
  targetItem: CollectibleItem | null;
  config: HookConfig;
  startX: number;
  startY: number;
  stunTimer: number;           // 眩晕计时器
  direction: HookDirection;
}

// 状态机事件
type HookEvent =
  | { type: 'LAUNCH'; direction: HookDirection }
  | { type: 'REACH_MAX_LENGTH' }
  | { type: 'HIT_ITEM'; item: CollectibleItem }
  | { type: 'HIT_WALL' }
  | { type: 'ITEM_CAUGHT' }
  | { type: 'RETURN_TO_BASE' }
  | { type: 'STUN'; duration: number }
  | { type: 'STUN_END' }
  | { type: 'RESET' }
  | { type: 'TICK'; deltaTime: number };

// 状态接口
interface HookStateHandler {
  enter(ctx: HookContext): void;
  update(ctx: HookContext, event: HookEvent): HookState | null;
  exit(ctx: HookContext): void;
}

// 状态处理程序映射
const stateHandlers: Record<HookState, HookStateHandler> = {
  [HookState.IDLE]: {
    enter(ctx: HookContext) {
      ctx.length = 0;
      ctx.velocity = 0;
      ctx.caughtItem = null;
      ctx.targetItem = null;
    },
    update(ctx: HookContext, event: HookEvent): HookState | null {
      if (event.type === 'LAUNCH') {
        ctx.direction = event.direction;
        return HookState.EXTENDING;
      }
      if (event.type === 'STUN') {
        ctx.stunTimer = event.duration;
        return HookState.STUNNED;
      }
      return null;
    },
    exit(ctx: HookContext) {}
  },

  [HookState.EXTENDING]: {
    enter(ctx: HookContext) {
      ctx.startX = ctx.x;
      ctx.startY = ctx.y;
    },
    update(ctx: HookContext, event: HookEvent): HookState | null {
      if (event.type === 'TICK') {
        // 计算速度（带加速度）
        ctx.velocity += ctx.config.acceleration * event.deltaTime;
        ctx.velocity = Math.min(ctx.velocity, ctx.config.baseSpeed);

        // 更新长度
        ctx.length += ctx.velocity * event.deltaTime;

        // 边界检查 - 达到最大长度
        if (ctx.length >= ctx.config.maxLength) {
          return HookState.RETRACTING;
        }
      }

      if (event.type === 'HIT_ITEM') {
        ctx.targetItem = event.item;
        return HookState.CATCHING;
      }

      if (event.type === 'HIT_WALL') {
        return HookState.RETRACTING;
      }

      if (event.type === 'STUN') {
        ctx.stunTimer = event.duration;
        return HookState.STUNNED;
      }

      return null;
    },
    exit(ctx: HookContext) {}
  },

  [HookState.CATCHING]: {
    enter(ctx: HookContext) {
      // 检查是否能抓住物品（基于拉力和物品重量）
      if (ctx.targetItem && ctx.config.basePower >= ctx.targetItem.weight) {
        ctx.caughtItem = ctx.targetItem;
        ctx.caughtItem.isCaught = true;
      }
    },
    update(ctx: HookContext, event: HookEvent): HookState | null {
      if (event.type === 'TICK') {
        // 抓取动画/过程
        if (ctx.caughtItem) {
          return HookState.RETURNING;
        } else {
          // 抓取失败，物品太重
          return HookState.RETRACTING;
        }
      }
      return null;
    },
    exit(ctx: HookContext) {}
  },

  [HookState.RETURNING]: {
    enter(ctx: HookContext) {
      if (ctx.caughtItem) {
        // 根据物品重量计算收回速度
        const weightFactor = Math.max(0.2, 1 - (ctx.caughtItem.weight / (ctx.config.basePower * 2)));
        ctx.velocity = ctx.config.baseSpeed * ctx.config.retractSpeedMultiplier * weightFactor;
      }
    },
    update(ctx: HookContext, event: HookEvent): HookState | null {
      if (event.type === 'TICK') {
        // 向回移动
        ctx.length -= ctx.velocity * event.deltaTime;

        // 更新被抓物品位置
        if (ctx.caughtItem) {
          ctx.caughtItem.x = ctx.x + Math.cos(ctx.direction) * ctx.length;
          ctx.caughtItem.y = ctx.y + Math.sin(ctx.direction) * ctx.length;
        }

        // 回到起点
        if (ctx.length <= 0) {
          return HookState.CAUGHT;
        }
      }

      if (event.type === 'STUN') {
        ctx.stunTimer = event.duration;
        return HookState.STUNNED;
      }

      return null;
    },
    exit(ctx: HookContext) {}
  },

  [HookState.RETRACTING]: {
    enter(ctx: HookContext) {
      ctx.velocity = ctx.config.baseSpeed * 0.8;
    },
    update(ctx: HookContext, event: HookEvent): HookState | null {
      if (event.type === 'TICK') {
        ctx.length -= ctx.velocity * event.deltaTime;

        if (ctx.length <= 0) {
          return HookState.MISSED;
        }
      }

      if (event.type === 'STUN') {
        ctx.stunTimer = event.duration;
        return HookState.STUNNED;
      }

      return null;
    },
    exit(ctx: HookContext) {}
  },

  [HookState.CAUGHT]: {
    enter(ctx: HookContext) {
      // 处理获得的物品
      if (ctx.caughtItem) {
        console.log(`获得物品: ${ctx.caughtItem.type}, 价值: ${ctx.caughtItem.value}`);
      }
    },
    update(ctx: HookContext, event: HookEvent): HookState | null {
      if (event.type === 'RESET' || event.type === 'RETURN_TO_BASE') {
        return HookState.IDLE;
      }
      return null;
    },
    exit(ctx: HookContext) {}
  },

  [HookState.MISSED]: {
    enter(ctx: HookContext) {
      console.log('未抓中任何物品');
    },
    update(ctx: HookContext, event: HookEvent): HookState | null {
      if (event.type === 'RESET' || event.type === 'RETURN_TO_BASE') {
        return HookState.IDLE;
      }
      return null;
    },
    exit(ctx: HookContext) {}
  },

  [HookState.STUNNED]: {
    enter(ctx: HookContext) {
      console.log(`钩子眩晕中，剩余时间: ${ctx.stunTimer}秒`);
    },
    update(ctx: HookContext, event: HookEvent): HookState | null {
      if (event.type === 'TICK') {
        ctx.stunTimer -= event.deltaTime;
        if (ctx.stunTimer <= 0) {
          return HookState.IDLE;
        }
      }
      return null;
    },
    exit(ctx: HookContext) {}
  }
};

// 钩子状态机类
class HookStateMachine {
  private ctx: HookContext;
  private currentState: HookState;

  constructor(config: Partial<HookConfig> = {}) {
    this.ctx = {
      state: HookState.IDLE,
      x: 0,
      y: 0,
      angle: 0,
      length: 0,
      velocity: 0,
      caughtItem: null,
      targetItem: null,
      config: {
        maxLength: config.maxLength ?? 300,
        baseSpeed: config.baseSpeed ?? 200,
        basePower: config.basePower ?? 50,
        acceleration: config.acceleration ?? 50,
        friction: config.friction ?? 0.9,
        catchRadius: config.catchRadius ?? 20,
        retractSpeedMultiplier: config.retractSpeedMultiplier ?? 0.8
      },
      startX: 0,
      startY: 0,
      stunTimer: 0,
      direction: HookDirection.RIGHT
    };
    this.currentState = HookState.IDLE;

    // 进入初始状态
    stateHandlers[HookState.IDLE].enter(this.ctx);
  }

  // 发送事件到状态机
  dispatch(event: HookEvent): void {
    const handler = stateHandlers[this.currentState];
    const newState = handler.update(this.ctx, event);

    if (newState && newState !== this.currentState) {
      // 退出当前状态
      handler.exit(this.ctx);

      // 进入新状态
      this.currentState = newState;
      this.ctx.state = newState;
      stateHandlers[newState].enter(this.ctx);
    }
  }

  // 获取当前状态
  getState(): HookState {
    return this.currentState;
  }

  // 获取上下文
  getContext(): HookContext {
    return this.ctx;
  }

  // 获取钩子末端位置
  getHookEndPosition(): { x: number; y: number } {
    return {
      x: this.ctx.x + Math.cos(this.ctx.direction) * this.ctx.length,
      y: this.ctx.y + Math.sin(this.ctx.direction) * this.ctx.length
    };
  }

  // 重置状态机
  reset(): void {
    this.dispatch({ type: 'RESET' });
  }

  // 检测碰撞
  checkCollision(items: CollectibleItem[]): CollectibleItem | null {
    const hookEnd = this.getHookEndPosition();

    for (const item of items) {
      if (item.isCaught) continue;

      const distance = Math.sqrt(
        Math.pow(hookEnd.x - item.x, 2) + 
        Math.pow(hookEnd.y - item.y, 2)
      );

      if (distance <= this.ctx.config.catchRadius + item.radius) {
        return item;
      }
    }

    return null;
  }

  // 每帧更新
  update(deltaTime: number): void {
    // 检测碰撞
    if (this.currentState === HookState.EXTENDING) {
      // 这里需要传入物品列表进行碰撞检测
      // const hitItem = this.checkCollision(items);
      // if (hitItem) {
      //   this.dispatch({ type: 'HIT_ITEM', item: hitItem });
      // }
    }

    this.dispatch({ type: 'TICK', deltaTime });
  }
}

export { HookStateMachine, HookState, HookDirection, HookEvent, HookContext, HookConfig, CollectibleItem };
